from itertools import combinations
from collections import defaultdict
import time

def intersection(dataset):
    intersection = set(dataset[0])
    for lst in dataset[1:]:
        lst.sort()
        intersection &= set(lst)
    return intersection
def count_subsets_incremental(nested_list):
    subset_count = {}
    max_length = max(len(lst) for lst in nested_list)

    for length in range(max_length, 0, -1):
        current_subsets = {}

        for lst in nested_list:
            if len(lst) >= length:
                for subset in combinations(lst, length):
                    if subset in current_subsets:
                        current_subsets[subset] += 1
                    else:
                        current_subsets[subset] = 1

        for subset, count in current_subsets.items():
            update_count = True
            subset_set = set(subset)
            for longer_subset, longer_count in subset_count.items():
                if len(longer_subset) > length and subset_set.issubset(longer_subset):
                    if longer_count == count:
                        update_count = False
                        break

            if update_count:
                subset_count[subset] = count

    return subset_count



